test("harness: this file is discoverable by the repo's `node --test` script", () => {
  // package.json runs `node --test`, which discovers `*.test.mjs`; integration
  // coverage only counts if this filename matches that discovery pattern.
  assert.match(basename(fileURLToPath(import.meta.url)), /\.test\.mjs$/);
});

test('harness: the integration tests use only the two modules and Node built-ins', async () => {
  const { readFileSync } = await import('node:fs');
  const source = readFileSync(fileURLToPath(new URL('./integration.test.mjs', import.meta.url)), 'utf8');
  const specs = [...source.matchAll(/^import[^'"]*['"]([^'"]+)['"]/gm)].map((m) => m[1]);

  assert.ok(specs.includes('../src/csv.mjs'), 'must compose the CSV workstream');
  assert.ok(specs.includes('../src/search.mjs'), 'must compose the search workstream');
  assert.deepEqual(
    specs.filter((spec) => !spec.startsWith('node:') && !spec.startsWith('../')),
    [],
    `unexpected non-builtin imports: ${specs.join(', ')}`,
  );
  assert.equal(/\bfetch\(|\bnode:(http|https|net|dns|tls|worker)\b/.test(source), false, 'no network services');
});
